  function getCanonical(filename) {
    if (!filename) return '';
    const base = filename.split('/').pop().replace('.gif', '.webp');
    return CANONICAL_MAP[base] || base;
  }

  function getCategory(filename) {
    const base = getCanonical(filename);
    if (COUPLE_SET.has(base)) return 'couple';
    if (BUBU_SET.has(base)) return 'bubu';
    return 'dudu';
  }

  function resolveStickerPath(filename) {
    if (!filename) return '';
    const base = getCanonical(filename);
    const cat = getCategory(base);
    return `assets/stickers_${cat}/${base}`;
  }

  function handleImageError(img, originalPath) {
    if (!img) return;
    img.onerror = null;
    const raw = originalPath || img.getAttribute('src') || '';
    const base = getCanonical(raw);
    const cat = getCategory(base);
    const serverBase = window.DuduChatSocket?.getHttpBaseUrl?.() || 'https://chat.nexora-v1.my.id';
    const remoteUrl = `${serverBase}/assets/stickers_${cat}/${base}`;
    if (img.src !== remoteUrl) {
      img.src = remoteUrl;
    } else {
      img.src = 'assets/stickers_dudu/STK-20260307-WA0001.webp';
    }
  }

