  function isCoupleVerb(word) {
    if (!word) return false;
    if (COUPLE_VERBS.has(word)) return true;
    for (const v of COUPLE_VERBS) {
      if (word.includes(v)) return true;
    }
    return false;
  }

  function matchClusterKey(word) {
    if (!word) return null;
    for (const c of EMOTION_CLUSTERS) {
      if (c.key === word || c.words.includes(word)) return c.key;
      for (const w of c.words) {
        if (word.includes(w) || w.includes(word)) return c.key;
      }
    }
    return null;
  }

